import unittest


class T(unittest.TestCase):
    def test_equal(self):
        self.assertEqual(0.1 + 0.2, 0.3)

    def test_almost(self):
        self.assertAlmostEqual(0.1 + 0.2, 0.3)

    def test_places(self):
        self.assertAlmostEqual(1.0, 1.01, places=1)


result = unittest.TestResult()
unittest.defaultTestLoader.loadTestsFromTestCase(T).run(result)
print(result.testsRun, len(result.failures))
print(sorted(t.id().split(".")[-1] for t, _ in result.failures))
